import Complex128Array = require( '@stdlib/array/complex128' );
import ztpmv = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const AP = new Complex128Array( 20 );
	const x = new Complex128Array( 10 );

	ztpmv( 'row-major', 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const AP = new Complex128Array( 20 );
	const x = new Complex128Array( 10 );

	ztpmv( 10, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( true, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( false, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( null, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( undefined, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( [], 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( {}, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
	ztpmv( ( x: number ): number => x, 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1 ); // $ExpectError
}

