// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const AP = new Complex128Array( 20 );
	const x = new Complex128Array( 10 );

	ztpmv(); // $ExpectError
	ztpmv( 'row-major' ); // $ExpectError
	ztpmv( 'row-major', 'lower' ); // $ExpectError
	ztpmv( 'row-major', 'lower', 'no-transpose' ); // $ExpectError
	ztpmv( 'row-major', 'lower', 'no-transpose', 'non-unit' ); // $ExpectError
	ztpmv( 'row-major', 'lower', 'no-transpose', 'non-unit', 10 ); // $ExpectError
	ztpmv( 'row-major', 'lower', 'no-transpose', 'non-unit', 10, AP ); // $ExpectError
	ztpmv( 'row-major', 'lower', 'no-transpose', 'non-unit', 10, AP, x ); // $ExpectError
	ztpmv( 'row-major', 'lower', 'no-transpose', 'non-unit', 10, AP, x, 1, 1 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex128Array...
{
	const AP = new Complex128Array( 20 );
	const x = new Complex128Array( 10 );

	ztpmv.ndarray( 'row-major', 'lower', 'no-transpose', 'non-unit', 10, AP, 1, 0, x, 1, 0 ); // $ExpectType Complex128Array
}

